using XmlReader reader \= XmlReader.Create("https://example.com/feed.xml");
SyndicationFeed feed \= SyndicationFeed.Load(reader);

foreach (SyndicationItem item in feed.Items)
{
    Console.WriteLine(item.Title.Text);
